 */
private static function opensWith(SimpleXMLElement $element, array $seen): array
{
    if ($element->getName() === 'kw') {
        return [trim((string) $element)];
    }
    if ($element->getName() === 'BNF') {
        return self::opensProduction((string) $element['name'], $seen);
