    public static function writeTo(string $name, array $files): string
    {
        $directory = sys_get_temp_dir().'/peq-corpus-'.md5($name.serialize($files));
        if (!is_dir($directory) && !mkdir($directory, 0o777, true) && !is_dir($directory)) {
