public static function assemble(array $rows, array $sends, array $receives, array $crossings, array $straight): self
{
    $fans = [];
    foreach ($sends as $origin => $sent) {
        if ($sent['targets'] !== [] || $sent['crossings'] !== []) {
            $fans[$origin] = new Lane([$origin], $sent['targets'], [], $sent['crossings']);
        }
    }
    $gathers = [];
    foreach ($receives as $target => $received) {
        if ($received['origins'] !== [] || $received['crossings'] !== []) {
            $gathers[$target] = new Lane($received['origins'], [$target], $received['crossings']);
        }
    }
    $lanes = [...self::arrange(array_values($fans), $rows), ...self::arrange(array_values($gathers), $rows)];

    $transfers = [];
    foreach ($crossings as [$origin, $target, $line]) {
        $transfers[] = [(int) array_search($fans[$origin], $lanes, true), (int) array_search($gathers[$target], $lanes, true), $line];
    }

    return new self($lanes, $straight, $transfers);
}

